RSpec.describe "timekeeping:alerts reference_unavailable rate" do
  let(:alerts_task_service_token) { "service-#{SecureRandom.hex(24)}" }
  include ActiveSupport::Testing::TimeHelpers

  def run_alerts_task_against(metrics_body)
    Rails.application.load_tasks if Rake::Task.tasks.empty?
    Rake::Task["timekeeping:alerts"].reenable
    stub_request(:get, "http://timekeeping.alerts.test/internal/v1/metrics")
      .with(headers: { "Authorization" => "Bearer #{alerts_task_service_token}" })
      .to_return(status: 200, body: JSON.generate(metrics_body), headers: { "Content-Type" => "application/json" })
    env_before = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    ENV["TIMEKEEPING_BASE_URL"] = "http://timekeeping.alerts.test"
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = alerts_task_service_token
    printed = StringIO.new
    original_stdout = $stdout
    $stdout = printed
    begin
      Rake::Task["timekeeping:alerts"].invoke
    rescue SystemExit
      nil
    ensure
      $stdout = original_stdout
      %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = env_before[key] }
    end
    printed.string.lines
  end

  it "alerts on reference_unavailable over 1% of writes plus refusals for the failing company only, and stays quiet at exactly 1%" do
    TimekeepingOwnership.ensure_initial!
    completed_window_start = "2026-03-03T12:00:00Z"
    window = lambda do |writes, refused|
      { "window_start" => completed_window_start, "writes" => writes, "reference_unavailable" => refused,
        "latency_ms_sum" => 0, "latency_ms_buckets" => { "25" => writes + refused } }
    end
    body = {
      "window_seconds" => 300, "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf", "total_field" => "writes + reference_unavailable",
      # 2 of 100 requests refused: 2%. Company 102 has 1 of 100 refused: exactly 1%, which is not over 1%,
      # although 1 / 99 writes would be, so dividing by writes alone wrongly alerts it.
      "companies" => [
        { "company_id" => 101, "windows" => [window.call(98, 2)] },
        { "company_id" => 102, "windows" => [window.call(99, 1)] }
      ],
      "outbox_lag" => []
    }

    lines = travel_to(Time.utc(2026, 3, 3, 12, 7)) { run_alerts_task_against(body) }

    # "`503 reference_unavailable` over 1% of writes for 5 minutes;"
    # "It logs each alert with `company_id`."
    unavailable_alerts = lines.select { |line| line.include?("reference_unavailable") && !line.match?(/\bunavailable signal|not available/i) }
    expect(unavailable_alerts.count { |line| line.include?("company_id=101") }).to eq(1)
    expect(unavailable_alerts.none? { |line| line.include?("company_id=102") }).to be(true)
  end
end

