      %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = env_before[key] }
    end
    printed.string.lines
  end

  it "alerts on p95 entry write latency over 300 ms, including writes in the overflow bucket, and stays quiet at exactly 5% above 300 ms" do
    TimekeepingOwnership.ensure_initial!
    window = lambda do |buckets|
      { "window_start" => "2026-03-03T12:00:00Z", "writes" => buckets.values.sum, "reference_unavailable" => 0,
        "latency_ms_sum" => 0, "latency_ms_buckets" => buckets }
    end
    body = {
      "window_seconds" => 300, "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf", "total_field" => "writes + reference_unavailable",
      "companies" => [
        # Every write slower than 5000 ms, so only the overflow bucket reaches 95%.
        { "company_id" => 201, "windows" => [window.call({ "inf" => 20 })] },
        # 2 of 20 above 300 ms: 10%, so the p95 is above 300 ms.
        { "company_id" => 202, "windows" => [window.call({ "300" => 18, "500" => 2 })] },
        # 1 of 20 above 300 ms: exactly 5%, so the p95 is 300 ms, which is not over 300 ms.
        { "company_id" => 203, "windows" => [window.call({ "300" => 19, "500" => 1 })] }
      ],
      "outbox_lag" => []
    }

    lines = travel_to(Time.utc(2026, 3, 3, 12, 7)) { run_alerts_task_for_latency(body) }

    # "Timekeeping p95 latency for entry writes over 300 ms."
    latency_alerts = lines.select { |line| line.match?(/latency|p95/i) && !line.match?(/unavailable/i) }
    expect(latency_alerts.count { |line| line.include?("company_id=201") }).to eq(1)
    expect(latency_alerts.count { |line| line.include?("company_id=202") }).to eq(1)
    expect(latency_alerts.none? { |line| line.include?("company_id=203") }).to be(true)
  end
end

