    ENV["TIMEKEEPING_SERVICE_TOKEN"] = alerts_task_service_token
    printed = StringIO.new
    original_stdout = $stdout
    $stdout = printed
    begin
      Rake::Task["timekeeping:alerts"].invoke
    rescue SystemExit
      nil
    ensure
      $stdout = original_stdout
      %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = env_before[key] }
    end
    printed.string.lines
  end

  it "alerts on outbox lag over 5 minutes only when Timekeeping is the current owner" do
    TimekeepingOwnership.ensure_initial!
    lag_alert_for = ->(lines, company_id) { lines.count { |line| line.match?(/outbox/i) && !line.match?(/unavailable/i) && line.include?("company_id=#{company_id}") } }

    # "outbox lag (oldest unsent row age) of the current owner over 5 minutes;"
    monolith_owned = travel_to(Time.utc(2026, 3, 3, 12, 7)) { run_alerts_task_for_outbox_lag }
    expect(lag_alert_for.call(monolith_owned, 301)).to eq(0)

    TimekeepingOwnership.current.update_columns(owner: "timekeeping")
    timekeeping_owned = travel_to(Time.utc(2026, 3, 3, 12, 7)) { run_alerts_task_for_outbox_lag }
    expect(lag_alert_for.call(timekeeping_owned, 301)).to eq(1)
    expect(lag_alert_for.call(timekeeping_owned, 302)).to eq(0)
  end
end

RSpec.describe "timekeeping:alerts metrics read failure" do
  include ActiveSupport::Testing::TimeHelpers

  it "exits non-zero when the metrics read fails, still reports the monolith's own alerts and never prints the service token" do
    TimekeepingOwnership.ensure_initial!
    now = Time.utc(2026, 3, 3, 12, 30)
    company = create(:company)
    InvoiceOperationIntent.create!(company_id: company.id, invoice_id: 1, operation_id: SecureRandom.uuid,
                                   generation: 1, state: "pending", created_at: now - 3600)
    token = "alerts-secret-#{SecureRandom.hex(16)}"
    stub_request(:get, "http://timekeeping.alerts.test/internal/v1/metrics").to_return(status: 401, body: "")

    Rails.application.load_tasks if Rake::Task.tasks.empty?
    Rake::Task["timekeeping:alerts"].reenable
    env_before = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    ENV["TIMEKEEPING_BASE_URL"] = "http://timekeeping.alerts.test"
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = token
    printed = StringIO.new
    printed_errors = StringIO.new
    original_stdout = $stdout
    original_stderr = $stderr
    $stdout = printed
    $stderr = printed_errors
    exit_status = nil
    begin
      travel_to(now) { Rake::Task["timekeeping:alerts"].invoke }
    rescue SystemExit => e
      exit_status = e.status
    ensure
      $stdout = original_stdout
      $stderr = original_stderr
      %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = env_before[key] }
    end

    expect(exit_status).not_to be_nil
    expect(exit_status).not_to eq(0)
    # "It logs each alert with `company_id`." The intent alert comes from the monolith's own records,
    # so a failed Timekeeping read must not hide it.
    expect(printed.string.lines.count { |line| line.match?(/intent/i) && line.include?("company_id=#{company.id}") }).to eq(1)
    expect(printed.string + printed_errors.string).not_to include(token)
  end
end

